function ensureMembersSchema(){
  const cols=db.prepare("PRAGMA table_info('members')").all();
  const names=new Set(cols.map(c=>c.name));
  const badgeCol=cols.find(c=>c.name==='badge_number');
  const needsRebuild=!names.has('role') || !!badgeCol?.notnull;
  if(!needsRebuild){
    for(const [name,sql] of [
      ['attendance_token',"ALTER TABLE members ADD COLUMN attendance_token TEXT"],['plate',"ALTER TABLE members ADD COLUMN plate TEXT"],
      ['emergency_contact',"ALTER TABLE members ADD COLUMN emergency_contact TEXT"],
      ['phone',"ALTER TABLE members ADD COLUMN phone TEXT"],
      ['lat',"ALTER TABLE members ADD COLUMN lat REAL"],['lng',"ALTER TABLE members ADD COLUMN lng REAL"],['accuracy',"ALTER TABLE members ADD COLUMN accuracy REAL"],['last_seen',"ALTER TABLE members ADD COLUMN last_seen TEXT"],['live_started_at',"ALTER TABLE members ADD COLUMN live_started_at TEXT"],['live_until',"ALTER TABLE members ADD COLUMN live_until TEXT"]
    ]) if(!names.has(name)){try{db.exec(sql)}catch(e){}}
    return;
  }
  console.log('Migrating legacy members table to current schema...');
  const oldNames=new Set(cols.map(c=>c.name));
  const expr=(name,fallback='NULL')=>oldNames.has(name)?`"${name}"`:fallback;
  db.pragma('foreign_keys=OFF');
  const tx=db.transaction(()=>{
    db.exec(`DROP TABLE IF EXISTS members_migrated;CREATE TABLE members_migrated(id INTEGER PRIMARY KEY AUTOINCREMENT,token TEXT UNIQUE NOT NULL,attendance_token TEXT UNIQUE,badge_number TEXT UNIQUE,role TEXT NOT NULL DEFAULT 'member',full_name TEXT NOT NULL,nickname TEXT,motorcycle TEXT,plate TEXT,phone TEXT,emergency_contact TEXT,status TEXT NOT NULL DEFAULT 'pending',lat REAL,lng REAL,accuracy REAL,last_seen TEXT,live_started_at TEXT,live_until TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);`);
    db.exec(`INSERT OR IGNORE INTO members_migrated(id,token,attendance_token,badge_number,role,full_name,nickname,motorcycle,plate,phone,emergency_contact,status,lat,lng,accuracy,last_seen,live_started_at,live_until,created_at) SELECT ${expr('id')},${expr('token',"lower(hex(randomblob(24)))")},${expr('attendance_token','NULL')},NULLIF(${expr('badge_number',"''")},''),${expr('role',"'member'")},${expr('full_name',"'Unknown Member'")},${expr('nickname',"''")},${expr('motorcycle',"''")},${expr('plate',"''")},${expr('phone',"''")},${expr('emergency_contact',"''")},${expr('status',"'pending'")},${expr('lat')},${expr('lng')},${expr('accuracy')},${expr('last_seen')},${expr('live_started_at')},${expr('live_until')},${expr('created_at',"CURRENT_TIMESTAMP")} FROM members;`);
    db.exec('DROP TABLE members;ALTER TABLE members_migrated RENAME TO members;');
  });
  tx();
  db.pragma('foreign_keys=ON');
}
