const adminEmail=process.env.ADMIN_EMAIL||'admin@boyzofrosario.local',adminPassword=process.env.ADMIN_PASSWORD||'ChangeMe123!',MAX_ADMINS=8,primaryAdminName=process.env.ADMIN_NAME||'Primary Administrator';let primaryAdmin=db.prepare('SELECT id FROM admins WHERE lower(email)=lower(?)').get(adminEmail);if(!primaryAdmin){const x=db.prepare('INSERT INTO admins(full_name,email,password_hash) VALUES(?,?,?)').run(primaryAdminName,adminEmail,bcrypt.hashSync(adminPassword,12));primaryAdmin={id:x.lastInsertRowid}}if(!db.prepare('SELECT id FROM admin_profiles WHERE lower(full_name)=lower(?)').get(primaryAdminName))db.prepare('INSERT INTO admin_profiles(full_name,badge_number) VALUES(?,NULL)').run(primaryAdminName);
function normalizeBadge(v){const raw=String(v||'').trim();if(!raw||raw.toLowerCase()==='no-badge'||raw.toLowerCase()==='no badge')return null;const compact=raw.toUpperCase().replace(/\s+/g,'');let digitsOnly=compact;if(/^BOR-/.test(compact))digitsOnly=compact.slice(4);if(!/^\d{3}$/.test(digitsOnly))throw new Error('Badge number must be exactly 3 digits, for example 001.');return `BOR-${digitsOnly}`}
function normalizeName(v){return String(v||'').trim().toLowerCase().replace(/\s+/g,' ')}
function registrationDuplicate(fullName,phone,{excludeMemberId=null,noBadge=false}={}){const n=normalizeName(fullName),p=digits(phone);const rows=db.prepare('SELECT id,full_name,phone,badge_number FROM members'+(excludeMemberId?' WHERE id<>?':'')).all(...(excludeMemberId?[excludeMemberId]:[]));return rows.find(r=>{const sameName=normalizeName(r.full_name)===n;const rp=digits(r.phone);const samePhone=p.length>=7&&rp.length>=7&&rp===p;if(noBadge)return sameName||samePhone;return sameName&&samePhone})||null}
function badgeInUse(badge,{memberId=null,adminProfileId=null}={}){if(!badge)return false;const m=memberId==null?db.prepare('SELECT id FROM members WHERE badge_number=?').get(badge):db.prepare('SELECT id FROM members WHERE badge_number=? AND id<>?').get(badge,memberId);const a=adminProfileId==null?db.prepare('SELECT id FROM admin_profiles WHERE badge_number=?').get(badge):db.prepare('SELECT id FROM admin_profiles WHERE badge_number=? AND id<>?').get(badge,adminProfileId);return !!(m||a)}
const sessions=new Map();function makeSession(data){const sid=crypto.randomBytes(32).toString('hex');sessions.set(sid,{...data,expires:Date.now()+8*60*60*1000});return sid}function getSession(req){const raw=req.headers.cookie||'',m=raw.match(/(?:^|; )bor_session=([^;]+)/);if(!m)return null;const s=sessions.get(m[1]);if(!s||s.expires<Date.now()){sessions.delete(m[1]);return null}return{sid:m[1],...s}}function requireAdmin(req,res,next){const s=getSession(req);if(!s?.adminId)return res.status(401).json({error:'Admin authentication required.'});req.admin=s;next()}function setCookie(res,sid){res.setHeader('Set-Cookie',`bor_session=${sid}; HttpOnly; SameSite=Lax; Path=/; Max-Age=28800${process.env.NODE_ENV==='production'?'; Secure':''}`)}function clearCookie(res,sid){if(sid)sessions.delete(sid);res.setHeader('Set-Cookie','bor_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0')}
const MEMBER_COOKIE='bor_member_access',MEMBER_IDLE_MS=30*60*1000,memberSessionSecret=String(process.env.SESSION_SECRET||process.env.MEMBER_SESSION_SECRET||adminPassword||'bor-member-secret');function signMemberSession(memberId){const exp=Date.now()+MEMBER_IDLE_MS,payload=`${Number(memberId)}.${exp}`,sig=crypto.createHmac('sha256',memberSessionSecret).update(payload).digest('hex');return `${payload}.${sig}`}function readMemberSession(req){const raw=req.headers.cookie||'',m=raw.match(/(?:^|; )bor_member_access=([^;]+)/);if(!m)return null;const parts=decodeURIComponent(m[1]).split('.');if(parts.length!==3)return null;const [id,exp,sig]=parts,payload=`${id}.${exp}`,expected=crypto.createHmac('sha256',memberSessionSecret).update(payload).digest('hex');try{if(!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(expected)))return null}catch(e){return null}if(Number(exp)<Date.now())return null;const memberId=Number(id);if(!Number.isInteger(memberId)||memberId<1)return null;return {memberId}}function setMemberCookie(res,memberId){const v=signMemberSession(memberId);res.setHeader('Set-Cookie',`${MEMBER_COOKIE}=${encodeURIComponent(v)}; HttpOnly; SameSite=Lax; Path=/; Max-Age=1800${process.env.NODE_ENV==='production'?'; Secure':''}`)}function clearMemberCookie(res){res.setHeader('Set-Cookie',`${MEMBER_COOKIE}=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0`)}function requireMember(req,res,next){const s=readMemberSession(req);if(!s?.memberId)return res.status(401).json({error:'Member session expired. Please open your profile again.'});const m=db.prepare('SELECT id FROM members WHERE id=?').get(s.memberId);if(!m){clearMemberCookie(res);return res.status(401).json({error:'Member profile access expired.'})}req.memberId=s.memberId;setMemberCookie(res,s.memberId);next()}function digits(v){return String(v||'').replace(/\D/g,'')}
