app.post('/api/register',(req,res)=>{try{const {role='member',badgeNumber,fullName,nickname,motorcycle,phone,consent,adminInviteCode,adminEmail:ae,adminPassword:ap}=req.body||{};if(!consent)return res.status(400).json({error:'Please accept the community/location consent.'});const selected=String(role).toLowerCase()==='admin'?'admin':'member';if(selected==='admin'){const code=process.env.ADMIN_REGISTRATION_CODE;if(!code)return res.status(500).json({error:'Admin registration is not configured yet. Add ADMIN_REGISTRATION_CODE in Railway Variables.'});if(String(adminInviteCode||'')!==String(code))return res.status(403).json({error:'Invalid admin authorization code.'});if(!fullName||String(fullName).trim().length<2)return res.status(400).json({error:'Please enter the admin full name.'});const totalAdmins=db.prepare('SELECT COUNT(*) c FROM admin_profiles').get().c;if(totalAdmins>=MAX_ADMINS)return res.status(403).json({error:'Admin limit reached. Only 8 administrator names can be registered.'});const name=String(fullName).trim();if(db.prepare('SELECT id FROM admin_profiles WHERE lower(full_name)=lower(?)').get(name))return res.status(409).json({error:'That administrator name is already registered.'});let adminBadge=null;if(badgeNumber&&String(badgeNumber).trim().toLowerCase()!=='no-badge'){try{adminBadge=normalizeBadge(badgeNumber)}catch(e){return res.status(400).json({error:e.message})}if(db.prepare('SELECT id FROM members WHERE badge_number=?').get(adminBadge)||db.prepare('SELECT id FROM admin_profiles WHERE badge_number=?').get(adminBadge))return res.status(409).json({error:'That badge number is already registered.'});}db.prepare('INSERT INTO admin_profiles(full_name,badge_number) VALUES(?,?)').run(name,adminBadge);return res.status(201).json({ok:true,role:'admin',badgeNumber:adminBadge,message:'Administrator name registered. Use the shared admin email and password to sign in.'});}if(!fullName||String(fullName).trim().length<2)return res.status(400).json({error:'Please enter your full name.'});const cleanPhone=digits(phone);if(cleanPhone.length<7)return res.status(400).json({error:'A valid phone number is required so duplicate registrations can be prevented.'});let badge=null;try{badge=normalizeBadge(badgeNumber)}catch(e){return res.status(400).json({error:e.message})}if(badgeInUse(badge))return res.status(409).json({error:'That badge number is already registered. Each badge can only be registered once.'});const duplicate=registrationDuplicate(fullName,cleanPhone,{noBadge:!badge});if(duplicate)return res.status(409).json({error:badge?'This person already has a registration. Only one registration per member is allowed.':'This member is already registered without a badge. Double registration is not allowed.'});const token=crypto.randomBytes(24).toString('hex'),attendanceToken=crypto.randomBytes(24).toString('hex');const x=db.prepare('INSERT INTO members(badge_number,token,attendance_token,role,full_name,nickname,motorcycle,phone) VALUES(?,?,?,?,?,?,?,?)').run(badge,token,attendanceToken,'member',String(fullName).trim(),nickname||'',motorcycle||'',cleanPhone);setMemberCookie(res,x.lastInsertRowid);io.to('admins').emit('members:changed');return res.status(201).json({ok:true,memberId:x.lastInsertRowid,badgeNumber:badge,role:'member',memberUrl:'/member'});}catch(err){console.error('Registration error:',err);const msg=String(err&&err.message||err||'Unknown database error');return res.status(500).json({error:'Registration could not be saved. Please try again or contact an admin.',code:'REGISTRATION_DB_ERROR',details:msg.replace(/\n/g,' ').slice(0,240)});}});
function verifyBadge(req,res){Promise.resolve().then(async()=>{const raw=req.params.badge??req.query.badge??'';const badge=String(raw).trim().toUpperCase();if(!badge)return res.json({verified:false,registered:false,message:'No badge number registered yet.'});const m=db.prepare('SELECT id,badge_number,full_name,nickname,motorcycle,status,created_at,motorcycle_photo FROM members WHERE badge_number=?').get(badge);if(m){const verificationUrl=`${req.protocol}://${req.get('host')}/verify?badge=${encodeURIComponent(m.badge_number)}`,qrCode=await QRCode.toDataURL(verificationUrl,{width:240,margin:2});return res.json({verified:m.status==='approved',registered:true,role:'member',member:m,qrCode,verificationUrl,message:m.status==='approved'?'Legit approved member found.':`Registration found, but membership is ${m.status}.`});}const a=db.prepare('SELECT id,badge_number,full_name,created_at,motorcycle_photo FROM admin_profiles WHERE badge_number=?').get(badge);if(a){const verificationUrl=`${req.protocol}://${req.get('host')}/verify?badge=${encodeURIComponent(a.badge_number)}`,qrCode=await QRCode.toDataURL(verificationUrl,{width:240,margin:2});return res.json({verified:true,registered:true,role:'admin',member:{...a,status:'admin',nickname:null,motorcycle:null},qrCode,verificationUrl,message:'Registered administrator found.'});}return res.json({verified:false,registered:false,message:'No badge number registered yet.'});}).catch(err=>{console.error('Verification error:',err);if(!res.headersSent)res.status(500).json({error:'Unable to verify badge number right now.'})})}
