app.patch('/api/member/me/profile',requireMember,(req,res)=>{try{const m=db.prepare('SELECT id,badge_number,full_name,phone FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});const fullName=String(req.body?.fullName||'').trim();if(fullName.length<2)return res.status(400).json({error:'Full name is required.'});let badge=null;const raw=String(req.body?.badgeNumber||'').trim();if(raw){try{badge=normalizeBadge(raw)}catch(e){return res.status(400).json({error:e.message})}}if(badgeInUse(badge,{memberId:m.id}))return res.status(409).json({error:'That badge number is already registered to another member or administrator.'});const phone=digits(req.body?.phone);if(phone.length<7)return res.status(400).json({error:'A valid phone number is required.'});const duplicate=registrationDuplicate(fullName,phone,{excludeMemberId:m.id,noBadge:!badge});if(duplicate)return res.status(409).json({error:'Those details already belong to another registered member.'});db.prepare("UPDATE members SET badge_number=?,full_name=?,nickname=?,motorcycle=?,phone=? WHERE id=?").run(badge,fullName,String(req.body?.nickname||'').trim(),String(req.body?.motorcycle||'').trim(),phone,m.id);io.to('admins').emit('members:changed');res.json({ok:true,message:'Profile updated successfully.'});}catch(err){console.error('Member profile update error:',err);res.status(500).json({error:'Unable to update your profile right now.'})}});
app.get('/api/member/me/motorcycle-photo-status',requireMember,(req,res)=>{const m=db.prepare('SELECT motorcycle_photo,motorcycle_photo_changes,motorcycle_photo_extra_credits FROM members WHERE id=?').get(req.memberId);const pending=db.prepare("SELECT id,requested_at FROM motorcycle_photo_change_requests WHERE member_id=? AND status='pending' ORDER BY id DESC LIMIT 1").get(req.memberId);res.json({hasPhoto:!!m.motorcycle_photo,photo:m.motorcycle_photo||null,freeChangesUsed:Number(m.motorcycle_photo_changes||0),freeChangesRemaining:Math.max(0,5-Number(m.motorcycle_photo_changes||0)),extraCredits:Number(m.motorcycle_photo_extra_credits||0),canRequest:Number(m.motorcycle_photo_changes||0)>=5&&Number(m.motorcycle_photo_extra_credits||0)<1&&!pending,pendingRequest:pending||null})});
app.post('/api/member/me/motorcycle-photo',requireMember,upload.single('photo'),(req,res)=>{try{if(!req.file)return res.status(400).json({error:'Choose a JPG, PNG or WebP motorcycle photo up to 5 MB.'});const m=db.prepare('SELECT motorcycle_photo,motorcycle_photo_changes,motorcycle_photo_extra_credits FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});let used=Number(m.motorcycle_photo_changes||0),credits=Number(m.motorcycle_photo_extra_credits||0);const replacing=!!m.motorcycle_photo;if(replacing){if(used<5)used+=1;else if(credits>0)credits-=1;else return res.status(403).json({error:'You already used all 5 free motorcycle-photo changes. Request one-time change access from an administrator.'});}const data=`data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;db.prepare('UPDATE members SET motorcycle_photo=?,motorcycle_photo_changes=?,motorcycle_photo_extra_credits=? WHERE id=?').run(data,used,credits,req.memberId);if(replacing&&Number(m.motorcycle_photo_changes||0)>=5&&Number(m.motorcycle_photo_extra_credits||0)>credits){db.prepare("UPDATE motorcycle_photo_change_requests SET status='used' WHERE member_id=? AND status='approved' ORDER BY id DESC LIMIT 1").run(req.memberId)}io.to('admins').emit('motorcycle-photo:changed',{memberId:req.memberId});res.json({ok:true,photo:data,freeChangesUsed:used,freeChangesRemaining:Math.max(0,5-used),extraCredits:credits})}catch(err){console.error('Motorcycle photo upload error:',err);res.status(500).json({error:'Unable to save motorcycle photo.'})}});
app.post('/api/member/me/motorcycle-photo-request',requireMember,(req,res)=>{const m=db.prepare('SELECT motorcycle_photo_changes,motorcycle_photo_extra_credits FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});if(Number(m.motorcycle_photo_changes||0)<5)return res.status(400).json({error:'The request button becomes available only after all 5 free photo changes are used.'});if(Number(m.motorcycle_photo_extra_credits||0)>0)return res.status(400).json({error:'You already have one approved motorcycle-photo change available.'});if(db.prepare("SELECT id FROM motorcycle_photo_change_requests WHERE member_id=? AND status='pending'").get(req.memberId))return res.status(409).json({error:'You already have a pending request.'});db.prepare("INSERT INTO motorcycle_photo_change_requests(member_id,status) VALUES(?,'pending')").run(req.memberId);io.to('admins').emit('motorcycle-photo:request');res.status(201).json({ok:true,message:'Change request sent to the administrators.'})});
function activeLiveRows(){return db.prepare(`SELECT id,badge_number,full_name,nickname,motorcycle,lat,lng,accuracy,last_seen,live_started_at,live_until FROM members WHERE status='approved' AND lat IS NOT NULL AND lng IS NOT NULL AND live_until IS NOT NULL AND julianday(live_until)>julianday('now') ORDER BY badge_number,full_name`).all()}
function clearExpiredLive(){const expired=db.prepare(`SELECT id FROM members WHERE live_until IS NOT NULL AND julianday(live_until)<=julianday('now')`).all();if(!expired.length)return;const clear=db.prepare('UPDATE members SET lat=NULL,lng=NULL,accuracy=NULL,last_seen=NULL,live_started_at=NULL,live_until=NULL WHERE id=?');const tx=db.transaction(rows=>rows.forEach(r=>clear.run(r.id)));tx(expired);for(const r of expired){io.to('admins').emit('member:location:end',{id:r.id});io.to('members-live').emit('member:location:end',{id:r.id})}}
app.get('/api/member/live-locations',requireMember,(req,res)=>{clearExpiredLive();res.json({expiresMinutes:60,members:activeLiveRows()})});
app.post('/api/member/me/live/start',requireMember,(req,res)=>{const m=db.prepare('SELECT id,status FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});if(m.status!=='approved')return res.status(403).json({error:'Your membership must be approved before going live.'});const started=new Date(),until=new Date(started.getTime()+60*60*1000);db.prepare('UPDATE members SET live_started_at=?,live_until=?,lat=NULL,lng=NULL,accuracy=NULL,last_seen=NULL WHERE id=?').run(started.toISOString(),until.toISOString(),m.id);io.to('admins').emit('member:location:start',{id:m.id,liveStartedAt:started.toISOString(),liveUntil:until.toISOString()});io.to('members-live').emit('member:location:start',{id:m.id,liveStartedAt:started.toISOString(),liveUntil:until.toISOString()});res.json({ok:true,liveStartedAt:started.toISOString(),liveUntil:until.toISOString(),minutes:60})});
app.post('/api/member/me/location',requireMember,(req,res)=>{const m=db.prepare('SELECT id,badge_number,full_name,nickname,motorcycle,status,live_until FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});if(m.status!=='approved')return res.status(403).json({error:'Your membership must be approved before sharing live location.'});if(!m.live_until||Date.parse(m.live_until)<=Date.now()){db.prepare('UPDATE members SET lat=NULL,lng=NULL,accuracy=NULL,last_seen=NULL,live_started_at=NULL,live_until=NULL WHERE id=?').run(m.id);return res.status(409).json({error:'Your 60-minute live session has ended. Tap Go Live to start a new session.'})}const lat=Number(req.body?.lat),lng=Number(req.body?.lng),accuracy=Number(req.body?.accuracy||0);if(!Number.isFinite(lat)||lat<-90||lat>90||!Number.isFinite(lng)||lng<-180||lng>180)return res.status(400).json({error:'Invalid location coordinates.'});const lastSeen=new Date().toISOString();db.prepare('UPDATE members SET lat=?,lng=?,accuracy=?,last_seen=? WHERE id=?').run(lat,lng,Number.isFinite(accuracy)?Math.max(0,accuracy):0,lastSeen,m.id);const payload={id:m.id,badge_number:m.badge_number,full_name:m.full_name,nickname:m.nickname,motorcycle:m.motorcycle,lat,lng,accuracy,last_seen:lastSeen,live_until:m.live_until};io.to('admins').emit('member:location',payload);io.to('members-live').emit('member:location',payload);res.json({ok:true,lastSeen,liveUntil:m.live_until})});
app.post('/api/member/me/live/stop',requireMember,(req,res)=>{db.prepare('UPDATE members SET lat=NULL,lng=NULL,accuracy=NULL,last_seen=NULL,live_started_at=NULL,live_until=NULL WHERE id=?').run(req.memberId);io.to('admins').emit('member:location:end',{id:req.memberId});io.to('members-live').emit('member:location:end',{id:req.memberId});res.json({ok:true})});
setInterval(clearExpiredLive,60*1000);

app.get('/api/member/me/attendance-events',requireMember,(req,res)=>{const rows=db.prepare(`SELECT id,name,event_date FROM events ORDER BY event_date DESC,id DESC`).all();res.json(rows)});
app.get('/api/member/me/attendance-proof/:eventId',requireMember,(req,res)=>{const p=db.prepare('SELECT id,event_id,member_id,submitted_at FROM attendance_proofs WHERE event_id=? AND member_id=?').get(req.params.eventId,req.memberId);res.json({ok:true,submitted:!!p,proof:p||null})});
app.post('/api/member/me/attendance-proof',requireMember,upload.single('venuePhoto'),(req,res)=>{try{const eventId=Number(req.body?.eventId);const e=db.prepare('SELECT id,name,event_date FROM events WHERE id=?').get(eventId);if(!e)return res.status(404).json({error:'Event not found.'});const m=db.prepare('SELECT id,full_name,status FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});if(m.status!=='approved')return res.status(403).json({error:'Your membership must be approved before submitting event attendance.'});if(!req.file)return res.status(400).json({error:'A venue photo is required before your attendance QR can be used.'});const photo=`data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;db.prepare(`INSERT INTO attendance_proofs(event_id,member_id,photo_data,original_name,submitted_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(event_id,member_id) DO UPDATE SET photo_data=excluded.photo_data,original_name=excluded.original_name,submitted_at=CURRENT_TIMESTAMP`).run(e.id,m.id,photo,req.file.originalname||'venue-photo');res.json({ok:true,event:{id:e.id,name:e.name,eventDate:e.event_date},message:'Venue photo submitted. Your attendance QR is now ready for this event.'})}catch(err){console.error('Attendance proof error:',err);res.status(500).json({error:'Unable to save venue photo.'})}});
app.get('/api/member/me/attendance-qr',requireMember,(req,res)=>{Promise.resolve().then(async()=>{const eventId=Number(req.query.eventId);if(!eventId)return res.status(400).json({error:'Select an event and submit a venue photo first.'});const e=db.prepare('SELECT id,name,event_date FROM events WHERE id=?').get(eventId);if(!e)return res.status(404).json({error:'Event not found.'});const m=db.prepare('SELECT id,badge_number,full_name,status,attendance_token FROM members WHERE id=?').get(req.memberId);if(!m)return res.status(404).json({error:'Member not found.'});if(m.status!=='approved')return res.status(403).json({error:'Your membership must be approved before attendance can be recorded.'});const proof=db.prepare('SELECT id,submitted_at FROM attendance_proofs WHERE event_id=? AND member_id=?').get(e.id,m.id);if(!proof)return res.status(403).json({error:'Capture and submit a venue photo before showing your attendance QR.'});if(!m.attendance_token){let t;do{t=crypto.randomBytes(24).toString('hex')}while(db.prepare('SELECT id FROM members WHERE attendance_token=?').get(t));db.prepare('UPDATE members SET attendance_token=? WHERE id=?').run(t,m.id);m.attendance_token=t;}const payload=`BOR-ATTEND:${e.id}:${m.attendance_token}`;const qrCode=await QRCode.toDataURL(payload,{width:320,margin:2,errorCorrectionLevel:'M'});res.json({ok:true,qrCode,payload,badgeNumber:m.badge_number||null,fullName:m.full_name,status:m.status,event:{id:e.id,name:e.name,eventDate:e.event_date},proofSubmittedAt:proof.submitted_at});}).catch(err=>{console.error('Attendance QR error:',err);if(!res.headersSent)res.status(500).json({error:'Unable to generate attendance QR code.'})})});
app.get('/api/member/:token/attendance-qr',requireMember,(req,res)=>{res.status(410).json({error:'Use the official Member Portal attendance check-in. Select an event and submit a venue photo before generating your QR.'})});

