app.post('/api/admin/login',(req,res)=>{try{const {email,password}=req.body||{};const emailOk=String(email||'').trim().toLowerCase()===String(adminEmail).trim().toLowerCase();const passwordOk=String(password||'')===String(adminPassword);if(!emailOk||!passwordOk)return res.status(401).json({error:'Invalid admin email or password.'});setCookie(res,makeSession({adminId:primaryAdmin.id,email:adminEmail}));return res.json({ok:true,email:adminEmail});}catch(err){console.error('Admin login error:',err);return res.status(500).json({error:'Unable to sign in right now. Please try again.'})}});
