app.patch('/api/admin/admins/:id',requireAdmin,(req,res)=>{try{const id=Number(req.params.id),row=db.prepare('SELECT * FROM admin_profiles WHERE id=?').get(id);if(!row)return res.status(404).json({error:'Administrator not found.'});const fullName=String(req.body?.fullName||'').trim();if(fullName.length<2)return res.status(400).json({error:'Please enter the administrator name.'});let badge=null;const rawBadge=String(req.body?.badgeNumber||'').trim();if(rawBadge&&rawBadge.toLowerCase()!=='no-badge'&&rawBadge.toLowerCase()!=='no badge'){try{badge=normalizeBadge(rawBadge)}catch(e){return res.status(400).json({error:e.message})}const usedM=db.prepare('SELECT id FROM members WHERE badge_number=?').get(badge);const usedA=db.prepare('SELECT id FROM admin_profiles WHERE badge_number=? AND id<>?').get(badge,id);if(usedM||usedA)return res.status(409).json({error:'That badge number is already registered.'});}const dup=db.prepare('SELECT id FROM admin_profiles WHERE lower(full_name)=lower(?) AND id<>?').get(fullName,id);if(dup)return res.status(409).json({error:'That administrator name is already registered.'});const cleanUrl=v=>{v=String(v||'').trim();if(!v)return '';if(!/^https?:\/\//i.test(v))throw new Error('Social media links must start with http:// or https://');return v.slice(0,500)};const facebook=cleanUrl(req.body?.facebookUrl),instagram=cleanUrl(req.body?.instagramUrl),tiktok=cleanUrl(req.body?.tiktokUrl),youtube=cleanUrl(req.body?.youtubeUrl);db.prepare('UPDATE admin_profiles SET full_name=?,badge_number=?,facebook_url=?,instagram_url=?,tiktok_url=?,youtube_url=? WHERE id=?').run(fullName,badge,facebook,instagram,tiktok,youtube,id);res.json({ok:true});}catch(err){res.status(400).json({error:String(err.message||err)})}});
app.post('/api/admin/admins/:id/photo',requireAdmin,upload.single('photo'),(req,res)=>{const id=Number(req.params.id);if(!db.prepare('SELECT id FROM admin_profiles WHERE id=?').get(id))return res.status(404).json({error:'Administrator not found.'});if(!req.file)return res.status(400).json({error:'Please upload a supported image up to 5 MB.'});const data=`data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;db.prepare('UPDATE admin_profiles SET profile_photo=? WHERE id=?').run(data,id);res.json({ok:true,profilePhoto:data})});
app.post('/api/admin/profile/photo',requireAdmin,upload.single('photo'),(req,res)=>{if(!req.file)return res.status(400).json({error:'Please upload a supported image up to 5 MB.'});const data=`data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;db.prepare('UPDATE admins SET profile_photo=? WHERE id=?').run(data,req.admin.adminId);res.json({ok:true,profilePhoto:data})});
app.post('/api/admin/admins/:id/motorcycle-photo',requireAdmin,upload.single('photo'),(req,res)=>{try{const id=Number(req.params.id);if(!db.prepare('SELECT id FROM admin_profiles WHERE id=?').get(id))return res.status(404).json({error:'Administrator not found.'});if(!req.file)return res.status(400).json({error:'Choose a JPG, PNG or WebP motorcycle photo up to 5 MB.'});const data=`data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;db.prepare('UPDATE admin_profiles SET motorcycle_photo=? WHERE id=?').run(data,id);res.json({ok:true,motorcyclePhoto:data,message:'Admin motorcycle photo updated. Admin replacements are unlimited and do not require approval.'})}catch(err){console.error('Admin motorcycle photo upload error:',err);res.status(500).json({error:'Unable to save admin motorcycle photo.'})}});
app.get('/api/admin/members',requireAdmin,(req,res)=>res.json(db.prepare(`SELECT id,badge_number,role,full_name,nickname,motorcycle,phone,status,lat,lng,accuracy,last_seen,live_started_at,live_until,created_at,motorcycle_photo,motorcycle_photo_changes,motorcycle_photo_extra_credits FROM members ORDER BY CASE WHEN badge_number IS NULL OR badge_number='' THEN 1 ELSE 0 END, CASE WHEN substr(upper(badge_number),5) NOT GLOB '*[^0-9]*' THEN CAST(substr(upper(badge_number),5) AS INTEGER) ELSE 2147483647 END, upper(badge_number), upper(full_name)`).all()));
app.patch('/api/admin/members/:id',requireAdmin,(req,res)=>{const {badgeNumber,fullName,nickname,motorcycle,phone}=req.body||{};if(!fullName||String(fullName).trim().length<2)return res.status(400).json({error:'Full name is required.'});let badge=null;try{badge=normalizeBadge(badgeNumber)}catch(e){return res.status(400).json({error:e.message})}if(badgeInUse(badge,{memberId:Number(req.params.id)}))return res.status(409).json({error:'That badge number is already registered to a member or administrator.'});const cleanPhone=digits(phone);if(cleanPhone.length<7)return res.status(400).json({error:'A valid phone number is required.'});const duplicate=registrationDuplicate(fullName,cleanPhone,{excludeMemberId:Number(req.params.id),noBadge:!badge});if(duplicate)return res.status(409).json({error:'Those details already belong to another registered member.'});db.prepare("UPDATE members SET badge_number=?,role='member',full_name=?,nickname=?,motorcycle=?,phone=? WHERE id=?").run(badge,String(fullName).trim(),nickname||'',motorcycle||'',cleanPhone,req.params.id);io.to('admins').emit('members:changed');res.json({ok:true})});
app.patch('/api/admin/members/:id/status',requireAdmin,(req,res)=>{if(!['pending','approved','suspended'].includes(req.body.status))return res.status(400).json({error:'Invalid status.'});db.prepare('UPDATE members SET status=? WHERE id=?').run(req.body.status,req.params.id);io.to('admins').emit('members:changed');res.json({ok:true})});
