app.get('/api/admin/motorcycle-photo-requests',requireAdmin,(req,res)=>res.json(db.prepare(`SELECT r.id,r.member_id,r.status,r.requested_at,r.reviewed_at,m.badge_number,m.full_name,m.motorcycle,m.motorcycle_photo,m.motorcycle_photo_changes,m.motorcycle_photo_extra_credits FROM motorcycle_photo_change_requests r JOIN members m ON m.id=r.member_id ORDER BY CASE r.status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 WHEN 'used' THEN 2 ELSE 3 END,r.id DESC`).all()));
app.post('/api/admin/motorcycle-photo-requests/:id/approve',requireAdmin,(req,res)=>{const r=db.prepare("SELECT * FROM motorcycle_photo_change_requests WHERE id=? AND status='pending'").get(req.params.id);if(!r)return res.status(404).json({error:'Pending request not found.'});const tx=db.transaction(()=>{db.prepare("UPDATE motorcycle_photo_change_requests SET status='approved',reviewed_at=CURRENT_TIMESTAMP,reviewed_by=? WHERE id=?").run(req.admin.adminId,r.id);db.prepare('UPDATE members SET motorcycle_photo_extra_credits=motorcycle_photo_extra_credits+1 WHERE id=?').run(r.member_id)});tx();io.to('members-live').emit('motorcycle-photo:access',{memberId:r.member_id});res.json({ok:true,message:'One motorcycle-photo change was approved.'})});
app.post('/api/admin/motorcycle-photo-requests/:id/deny',requireAdmin,(req,res)=>{const r=db.prepare("SELECT * FROM motorcycle_photo_change_requests WHERE id=? AND status='pending'").get(req.params.id);if(!r)return res.status(404).json({error:'Pending request not found.'});db.prepare("UPDATE motorcycle_photo_change_requests SET status='denied',reviewed_at=CURRENT_TIMESTAMP,reviewed_by=? WHERE id=?").run(req.admin.adminId,r.id);res.json({ok:true})});

app.get('/api/admin/events',requireAdmin,(req,res)=>res.json(db.prepare(`SELECT e.id,e.name,e.event_date,e.created_at,e.photo_cover,COUNT(a.id) marked,COALESCE(SUM(CASE WHEN a.status='present' THEN 1 ELSE 0 END),0) present,(SELECT COUNT(*) FROM event_photos p WHERE p.event_id=e.id) photo_count FROM events e LEFT JOIN attendance a ON a.event_id=e.id GROUP BY e.id ORDER BY e.event_date DESC,e.id DESC`).all()));app.post('/api/admin/events',requireAdmin,(req,res)=>{const {name,eventDate}=req.body||{};if(!name||!eventDate)return res.status(400).json({error:'Event name and date are required.'});const x=db.prepare('INSERT INTO events(name,event_date) VALUES(?,?)').run(String(name).trim(),String(eventDate));res.status(201).json({ok:true,id:x.lastInsertRowid})});app.delete('/api/admin/events/:id',requireAdmin,(req,res)=>{db.prepare('DELETE FROM attendance WHERE event_id=?').run(req.params.id);db.prepare('DELETE FROM event_photos WHERE event_id=?').run(req.params.id);db.prepare('DELETE FROM attendance_proofs WHERE event_id=?').run(req.params.id);db.prepare('DELETE FROM events WHERE id=?').run(req.params.id);res.json({ok:true})});app.get('/api/admin/events/:id/attendance',requireAdmin,(req,res)=>res.json(db.prepare(`SELECT m.id,m.badge_number,m.full_name,m.nickname,COALESCE(a.status,'absent') attendance_status,a.checked_at,CASE WHEN p.id IS NULL THEN 0 ELSE 1 END has_proof,p.submitted_at proof_submitted_at FROM members m LEFT JOIN attendance a ON a.member_id=m.id AND a.event_id=? LEFT JOIN attendance_proofs p ON p.member_id=m.id AND p.event_id=? ORDER BY CASE WHEN m.badge_number IS NULL THEN 1 ELSE 0 END,m.badge_number,m.full_name`).all(req.params.id,req.params.id)));app.get('/api/admin/events/:eventId/members/:memberId/proof',requireAdmin,(req,res)=>{const p=db.prepare(`SELECT p.id,p.photo_data,p.original_name,p.submitted_at,m.full_name,m.badge_number,e.name event_name,e.event_date FROM attendance_proofs p JOIN members m ON m.id=p.member_id JOIN events e ON e.id=p.event_id WHERE p.event_id=? AND p.member_id=?`).get(req.params.eventId,req.params.memberId);if(!p)return res.status(404).json({error:'No venue photo submitted for this member and event.'});res.json(p)});app.post('/api/admin/events/:id/attendance',requireAdmin,(req,res)=>{const {memberId,status}=req.body||{},m=db.prepare('SELECT id FROM members WHERE id=?').get(memberId),e=db.prepare('SELECT id FROM events WHERE id=?').get(req.params.id);if(!m||!e||!['present','absent'].includes(status))return res.status(400).json({error:'Invalid member, event, or attendance status.'});if(status==='present'&&!db.prepare('SELECT id FROM attendance_proofs WHERE event_id=? AND member_id=?').get(e.id,m.id))return res.status(400).json({error:'Venue photo required. The member must capture and submit a photo at the venue before being marked present.'});db.prepare(`INSERT INTO attendance(event_id,member_id,status,checked_at) VALUES(?,?,?,?) ON CONFLICT(event_id,member_id) DO UPDATE SET status=excluded.status,checked_at=excluded.checked_at`).run(e.id,m.id,status,status==='present'?new Date().toISOString():null);res.json({ok:true})});
app.post('/api/admin/events/:id/scan-attendance',requireAdmin,(req,res)=>{try{const e=db.prepare('SELECT id,name,event_date FROM events WHERE id=?').get(req.params.id);if(!e)return res.status(404).json({error:'Event not found.'});const raw=String(req.body?.qrData||'').trim();const match=raw.match(/^BOR-ATTEND:(\d+):([a-f0-9]{48})$/i);if(!match)return res.status(400).json({error:'This attendance QR is invalid or was generated before venue-photo verification was enabled. Ask the member to submit a venue photo and generate a new QR.'});if(Number(match[1])!==Number(e.id))return res.status(400).json({error:'This QR was generated for a different event.'});const m=db.prepare('SELECT id,badge_number,full_name,status FROM members WHERE attendance_token=?').get(match[2]);if(!m)return res.status(404).json({error:'Member QR code is not registered.'});if(m.status!=='approved')return res.status(403).json({error:`${m.full_name} is not an approved member yet.`});const proof=db.prepare('SELECT id,submitted_at FROM attendance_proofs WHERE event_id=? AND member_id=?').get(e.id,m.id);if(!proof)return res.status(403).json({error:'Venue photo required. This member has not submitted a venue photo for the selected event.'});const prev=db.prepare('SELECT status,checked_at FROM attendance WHERE event_id=? AND member_id=?').get(e.id,m.id);const now=new Date().toISOString();db.prepare(`INSERT INTO attendance(event_id,member_id,status,checked_at) VALUES(?,?,'present',?) ON CONFLICT(event_id,member_id) DO UPDATE SET status='present',checked_at=excluded.checked_at`).run(e.id,m.id,now);res.json({ok:true,alreadyPresent:prev?.status==='present',member:{id:m.id,fullName:m.full_name,badgeNumber:m.badge_number||null},event:{id:e.id,name:e.name,eventDate:e.event_date},proofSubmittedAt:proof.submitted_at,checkedAt:now});}catch(err){console.error('Attendance scan error:',err);res.status(500).json({error:'Unable to record attendance from QR code.'})}});
app.get('/api/admin/events/:id/photos',requireAdmin,(req,res)=>res.json(db.prepare('SELECT id,photo_data,original_name,created_at FROM event_photos WHERE event_id=? ORDER BY id DESC').all(req.params.id)));app.post('/api/admin/events/:id/photos',requireAdmin,upload.array('photos',10),(req,res)=>{const e=db.prepare('SELECT id FROM events WHERE id=?').get(req.params.id);if(!e)return res.status(404).json({error:'Event not found.'});if(!req.files?.length)return res.status(400).json({error:'Please select at least one image.'});const ins=db.prepare('INSERT INTO event_photos(event_id,photo_data,original_name) VALUES(?,?,?)');db.transaction(fs=>fs.forEach(f=>ins.run(e.id,`data:${f.mimetype};base64,${f.buffer.toString('base64')}`,f.originalname)))(req.files);const c=db.prepare('SELECT photo_data FROM event_photos WHERE event_id=? ORDER BY id ASC LIMIT 1').get(e.id);if(c)db.prepare('UPDATE events SET photo_cover=? WHERE id=?').run(c.photo_data,e.id);res.json({ok:true,count:req.files.length})});app.delete('/api/admin/event-photos/:id',requireAdmin,(req,res)=>{const p=db.prepare('SELECT event_id FROM event_photos WHERE id=?').get(req.params.id);if(!p)return res.status(404).json({error:'Photo not found.'});db.prepare('DELETE FROM event_photos WHERE id=?').run(req.params.id);const c=db.prepare('SELECT photo_data FROM event_photos WHERE event_id=? ORDER BY id ASC LIMIT 1').get(p.event_id);db.prepare('UPDATE events SET photo_cover=? WHERE id=?').run(c?.photo_data||null,p.event_id);res.json({ok:true})});

app.get('/api/admin/gallery',requireAdmin,(req,res)=>res.json(db.prepare('SELECT id,title,photo_data,original_name,created_at FROM gallery_images ORDER BY id DESC').all()));
app.post('/api/admin/gallery',requireAdmin,upload.array('photos',10),(req,res)=>{try{if(!req.files?.length)return res.status(400).json({error:'Please select at least one image.'});const title=String(req.body?.title||'').trim().slice(0,100);const ins=db.prepare('INSERT INTO gallery_images(title,photo_data,original_name) VALUES(?,?,?)');db.transaction(files=>files.forEach(f=>ins.run(title,`data:${f.mimetype};base64,${f.buffer.toString('base64')}`,f.originalname)))(req.files);res.json({ok:true,count:req.files.length})}catch(err){console.error('Gallery upload error:',err);res.status(500).json({error:'Unable to store gallery images.'})}});
app.delete('/api/admin/gallery/:id',requireAdmin,(req,res)=>{const x=db.prepare('DELETE FROM gallery_images WHERE id=?').run(req.params.id);if(!x.changes)return res.status(404).json({error:'Stored image not found.'});res.json({ok:true})});
app.use('/api',(req,res)=>res.status(404).json({error:'API endpoint not found.'}));
io.on('connection',s=>{s.on('admin:join',()=>{const r={headers:{cookie:s.handshake.headers.cookie||''}};if(getSession(r)?.adminId)s.join('admins')});s.on('member:join-live',()=>{const r={headers:{cookie:s.handshake.headers.cookie||''}};const ms=readMemberSession(r);if(ms?.memberId&&db.prepare('SELECT id FROM members WHERE id=?').get(ms.memberId))s.join('members-live')})});
